<?php
require __DIR__.'/../includes/bootstrap.php';require_admin();$role=admin_role();$counts=['products'=>(int)db()->query('SELECT COUNT(*) FROM products')->fetchColumn(),'orders'=>(int)db()->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'new'=>(int)db()->query("SELECT COUNT(*) FROM orders WHERE status='new'")->fetchColumn(),'categories'=>(int)db()->query('SELECT COUNT(*) FROM categories')->fetchColumn()];$orders=db()->query('SELECT id,order_number,customer_name,phone,total,status,created_at FROM orders ORDER BY id DESC LIMIT 30')->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>لوحة تحكم <?=h(setting('store_name','الفخامة'))?></title><link rel="stylesheet" href="../assets/css/store.css"></head><body><div class="adminbar"><b><?=h(setting('store_name','الفخامة'))?> | لوحة الإدارة</b><span>مرحباً <?=h($_SESSION['admin_name'])?></span><a href="logout.php">تسجيل الخروج</a></div><main class="inner"><div class="adminnav"><?php if(in_array($role,['owner','assistant','products'],true)):?><a class="gold" href="products.php">إدارة المنتجات</a><a class="gold" href="categories.php">الأقسام</a><?php endif?><?php if(in_array($role,['owner','assistant'],true)):?><a class="gold" href="banners.php">البانرات</a><a class="gold" href="settings.php">إعدادات المتجر</a><?php endif?><?php if(in_array($role,['owner','assistant','orders'],true)):?><a class="gold" href="#orders">الطلبات</a><?php endif?><?php if($role==='owner'):?><a class="gold" href="staff.php">المديرون والموظفون</a><?php endif?></div><div class="stats"><div>المنتجات <b><?=$counts['products']?></b></div><div>الطلبات <b><?=$counts['orders']?></b></div><div>طلبات جديدة <b><?=$counts['new']?></b></div><div>الأقسام <b><?=$counts['categories']?></b></div></div><?php if(in_array($role,['owner','assistant','orders'],true)):?><h2 id="orders">أحدث الطلبات</h2><div class="table-wrap"><table><tr><th>رقم الطلب</th><th>العميل</th><th>الهاتف</th><th>الإجمالي</th><th>الحالة</th><th>التاريخ</th><th></th></tr><?php foreach($orders as $o):?><tr><td><?=h($o['order_number'])?></td><td><?=h($o['customer_name'])?></td><td><?=h($o['phone'])?></td><td><?=money($o['total'])?></td><td><?=h($o['status'])?></td><td><?=h($o['created_at'])?></td><td><a href="order.php?id=<?=$o['id']?>">عرض</a></td></tr><?php endforeach?></table></div><?php endif?></main></body></html>